mapper.select:
SELECT DISTINCT c.id, c.course_code, c.course_name, c.credit, c.course_category, c.description, c.total_hours, c.teacher_id, u.name AS teacher_name, c.course_status, c.semester, c.start_date, c.end_date FROM class_students cs JOIN course_classes cc ON cs.class_id = cc.id LEFT JOIN class_courses cc_c ON cc.id = cc_c.class_id LEFT JOIN courses c ON (cc_c.course_id = c.id OR (cc_c.course_id IS NULL AND cc.course_id = c.id)) LEFT JOIN users u ON (c.teacher_id = u.id OR (cc_c.teacher_id IS NOT NULL AND cc_c.teacher_id = u.id))
cs.student_id = #{studentId} AND c.id IS NOT NULL
AND c.course_status = #{courseStatus}
AND c.semester = #{semester}
AND c.course_category = #{courseCategory}
AND ( LOWER(c.course_name) LIKE CONCAT('%', LOWER(#{searchQuery}), '%') OR LOWER(u.name) LIKE CONCAT('%', LOWER(#{searchQuery}), '%') OR LOWER(c.course_code) LIKE CONCAT('%', LOWER(#{searchQuery}), '%') )
ORDER BY ${sortBy} ${order} LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(DISTINCT c.id) FROM class_students cs JOIN course_classes cc ON cs.class_id = cc.id LEFT JOIN class_courses cc_c ON cc.id = cc_c.class_id LEFT JOIN courses c ON (cc_c.course_id = c.id OR (cc_c.course_id IS NULL AND cc.course_id = c.id)) LEFT JOIN users u ON (c.teacher_id = u.id OR (cc_c.teacher_id IS NOT NULL AND cc_c.teacher_id = u.id))
cs.student_id = #{studentId} AND c.id IS NOT NULL
AND c.course_status = #{courseStatus}
AND c.semester = #{semester}
AND c.course_category = #{courseCategory}
AND ( LOWER(c.course_name) LIKE CONCAT('%', LOWER(#{searchQuery}), '%') OR LOWER(u.name) LIKE CONCAT('%', LOWER(#{searchQuery}), '%') OR LOWER(c.course_code) LIKE CONCAT('%', LOWER(#{searchQuery}), '%') )

SELECT -- 课程统计 (SELECT COUNT(DISTINCT cc.course_id) FROM class_students cs JOIN course_classes cc ON cs.class_id = cc.id JOIN courses c ON cc.course_id = c.id WHERE cs.student_id = #{studentId}
AND c.semester = #{semester}
AND c.id = #{courseId}
) AS totalCourses, (SELECT COUNT(DISTINCT cc.course_id) FROM class_students cs JOIN course_classes cc ON cs.class_id = cc.id JOIN courses c ON cc.course_id = c.id WHERE cs.student_id = #{studentId}
AND c.semester = #{semester}
AND c.id = #{courseId}
) AS pendingCourses,
-- 作业统计（通过assignment_classes表关联） (SELECT COUNT(DISTINCT a.id) FROM assignments a JOIN assignment_classes ac ON a.id = ac.assignment_id JOIN class_students cs ON ac.class_id = cs.class_id JOIN course_classes cc ON cs.class_id = cc.id JOIN courses c ON cc.course_id = c.id WHERE cs.student_id = #{studentId}
AND c.semester = #{semester}
AND c.id = #{courseId}
) AS totalAssignments, -- 已完成作业数：动态计算 (SELECT COUNT(DISTINCT asub.assignment_id) FROM assignment_submissions asub JOIN assignments a ON asub.assignment_id = a.id JOIN assignment_classes ac ON a.id = ac.assignment_id JOIN class_students cs ON ac.class_id = cs.class_id JOIN course_classes cc ON cs.class_id = cc.id JOIN courses c ON cc.course_id = c.id WHERE asub.student_id = #{studentId} AND CAST(asub.graded AS UNSIGNED) = 1
AND c.semester = #{semester}
AND c.id = #{courseId}
AND asub.submission_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 1 WEEK)
AND asub.submission_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 1 MONTH)
AND asub.submission_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 3 MONTH)
) AS completedAssignments, (SELECT COUNT(DISTINCT a.id) FROM assignments a JOIN assignment_classes ac ON a.id = ac.assignment_id JOIN class_students cs ON ac.class_id = cs.class_id JOIN course_classes cc ON cs.class_id = cc.id JOIN courses c ON cc.course_id = c.id WHERE cs.student_id = #{studentId} AND a.id NOT IN (SELECT assignment_id FROM assignment_submissions WHERE student_id = #{studentId})
AND c.semester = #{semester}
AND c.id = #{courseId}
) AS pendingAssignments,
-- 平均成绩：优先使用手工维护值，缺失时回退到动态计算（使用真实成绩） COALESCE( sp.average_score, (SELECT IFNULL(AVG(score), 0) FROM ( SELECT asub.score FROM assignment_submissions asub JOIN assignments a ON asub.assignment_id = a.id JOIN assignment_classes ac ON a.id = ac.assignment_id JOIN class_students cs ON ac.class_id = cs.class_id JOIN course_classes cc ON cs.class_id = cc.id JOIN courses c ON cc.course_id = c.id WHERE asub.student_id = #{studentId} AND asub.score IS NOT NULL AND CAST(asub.graded AS UNSIGNED) = 1
AND c.semester = #{semester}
AND c.id = #{courseId}
AND asub.submission_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 1 WEEK)
AND asub.submission_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 1 MONTH)
AND asub.submission_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 3 MONTH)
UNION ALL SELECT es.score FROM exam_submissions es JOIN exams e ON es.exam_id = e.id JOIN exam_classes ec ON e.id = ec.exam_id JOIN class_students cs ON ec.class_id = cs.class_id JOIN course_classes cc ON cs.class_id = cc.id JOIN courses c ON cc.course_id = c.id WHERE es.student_id = #{studentId} AND es.score IS NOT NULL AND CAST(es.graded AS UNSIGNED) = 1
AND c.semester = #{semester}
AND c.id = #{courseId}
AND es.submission_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 1 WEEK)
AND es.submission_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 1 MONTH)
AND es.submission_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 3 MONTH)
) AS all_scores) ) AS averageScore FROM (SELECT 1) AS d LEFT JOIN student_performance sp ON sp.student_id = #{studentId}

SELECT kp.id, kp.point_name AS name, CASE WHEN km.mastery_level = '优秀' THEN 90 WHEN km.mastery_level = '良好' THEN 75 WHEN km.mastery_level = '一般' THEN 60 WHEN km.mastery_level = '较差' THEN 40 ELSE 0 END AS mastery, c.course_name AS courseName FROM knowledge_points kp JOIN courses c ON kp.course_id = c.id JOIN class_students cs ON cs.student_id = #{studentId} LEFT JOIN knowledge_mastery km ON kp.id = km.knowledge_point_id AND cs.student_id = km.student_id WHERE ( -- 通过course_classes关联 EXISTS (SELECT 1 FROM course_classes cc WHERE cc.course_id = c.id AND cc.id = cs.class_id) OR -- 通过class_courses关联 EXISTS (SELECT 1 FROM class_courses clc WHERE clc.course_id = c.id AND clc.class_id = cs.class_id) )
AND c.semester = #{semester}
AND c.id = #{courseId}
GROUP BY kp.id, kp.point_name, c.course_name, km.mastery_level
